from pathlib import Path
import re
W=Path(__file__).resolve().parent
adds={
'art-155':'De verwijzing naar artikel 152 betekent concreet een openbare behandeling waar iedere schuldeiser voor of tegen homologatie kan spreken, persoonlijk, via een schriftelijk gemachtigde of via een advocaat; ook de schuldenaar kan zijn belangen verdedigen. Het schriftelijke verslag van de rechter-commissaris uit die bepaling wordt juist uitgezonderd. Het voorschrift van behandeling binnen twintig dagen is te onderscheiden van de acht dagen voor het instellen van beroep. De redactionele verwijzing naar overgangsrecht bij de wijziging van 2016 blijft behouden; daarmee is de toepasselijkheid op een oudere procedure nog niet afzonderlijk vastgesteld.',
'art-156':'Concreet sluit de insteltermijn aan op de acht dagen van artikel 154, nu gerekend ten opzichte van de hofbeslissing. Ook de snelle behandelingsregeling van artikel 155 wordt door de verwijzing betrokken. De toepasselijke cassatievoorschriften blijven relevant voor de procesvertegenwoordiging; de mogelijkheid persoonlijk op de homologatiezitting te spreken heft de vereisten voor het aanwenden van dit rechtsmiddel niet op.',
'art-157':'De woorden “alle” en “zonder uitzondering” hebben een wettelijke begrenzing: de Hoge Raad beperkt de binding tot voor verificatie vatbare concurrente vorderingen (HR 9 februari 2024, ECLI:NL:HR:2024:210, rov. 3.1–3.7). Voor zover zulke vorderingen door het akkoord onvoldaan blijven, bestaan zij als niet-afdwingbare natuurlijke verbintenissen voort. Tijdens faillissement lopende rente die artikel 128 van verificatie uitsluit, valt daarentegen buiten die binding. Een concurrente leverancier kan die rente na het einde nog vorderen, ook al is zijn verifieerbare hoofdsom door het akkoord beperkt. Dat is het oordeel van de Hoge Raad; het door de schuldenaar in die zaak verdedigde standpunt dat ook deze rente slechts een natuurlijke verbintenis zou zijn, is verworpen. [Zaakkaart en volledige bron](cases/HR-2024-210-akkoord-reikwijdte.md).',
'art-161a':'De beperking tot verifieerbare vorderingen is essentieel. Een door artikel 128 uitgesloten lopende rentevordering wordt niet door deze bepaling getroffen enkel omdat zij niet is ingediend. Dat sluit aan bij de afbakening in HR 2024:210, rov. 3.1–3.7, besproken bij artikel 157. Voor een werkelijk verifieerbare vordering moet eerst de concrete uiterste dag van artikel 127 worden vastgesteld: de rechter-commissaris kan de standaardtermijn aanpassen. De bronverwijzing naar overgangsrecht uit 2018 is bewaard; de geconsolideerde tekst beslecht niet zonder nader onderzoek welke regeling voor een oudere procedure geldt.',
'art-163':'De vereiste bewaring van alle goederen en gelden geldt zolang noch de storting noch voldoende zekerheid is geregeld. Is wél zekerheid gesteld, dan kan de curator niet uitsluitend op grond van deze bewaarplicht alle activa blijven vasthouden alsof zekerheid ontbreekt. Bij uitblijvende voldoening na een maand moet hij zelf uit de voorhanden baten betalen. Lid 3 ziet zowel op de begroting van het benodigde bedrag als op het aandeel van iedere voorrangsgerechtigde: een gezamenlijke reserve zonder onderliggende verdeling kan daardoor nadere vaststelling vergen.',
'art-168':'De verwijzing van lid 1 omvat artikel 13 lid 1 en de artikelen 15–18, plus de afdelingen over gevolgen, bestuur en voorzieningen en beheer. Zij verklaart niet artikel 13 lid 2 mede toepasselijk. Lid 2 bewaart de verificatie van oude vorderingen; lid 3 bewaart voor de oude schuldeisers het recht om de nu voor toelating ingediende vorderingen te betwisten. Die deelname is dus geen nieuw recht om elke vroeger erkende schuld opnieuw open te breken. Het overgangsrecht uit 2018 dat de officiële bron vermeldt, moet bij een oudere procedure afzonderlijk worden onderzocht.',
'art-171':'Bij drie even grote concurrente vorderingen van € 100, een akkoord van twintig procent, een oude crediteur die al € 20 kreeg, een oude crediteur zonder betaling en een nieuwe crediteur, dient de eerste € 40 van voldoende beschikbare verdelingsmiddelen eerst voor de laatste twee: elk € 20. De eerste oude crediteur ontvangt in die inhaalronde niets. Het restant wordt vervolgens gelijkelijk verdeeld naar de toepasselijke aanspraken; “gelijkelijk” betekent bij ongelijke vorderingsbedragen geen gelijk bedrag per persoon. Bij tekorten mag de boekhouding geen fictieve betaling van de ontbrekende akkoordpercentages opnemen.'
}
for p in (W/'commentary').glob('*.md'):
 s=p.read_text()
 def edit(m):
  k,t=m[1],m[2]
  if k in adds:
   if k=='art-171':
    pos=t.index('**Praktijkcontrole');t=t[:pos].rstrip()+'\n\n'+adds[k]+'\n\n'+t[pos:]
   else:t=t.rstrip()+'\n\n'+adds[k]+'\n\n'
  if k=='art-169':t=t.replace('De schuldenaar heeft in die periode weer zelfstandig aan het rechtsverkeer deelgenomen; heropening wist dat verkeer niet automatisch uit.','De bepaling beschermt het rechtsverkeer in de uitdrukkelijk genoemde tussenperiode; heropening wist dat verkeer niet automatisch uit. Het einde van het faillissement volgens artikel 161 treedt pas bij onherroepelijkheid in, terwijl artikel 169 voor zijn tijdvak al de homologatie als beginpunt noemt.')
  return '=== '+k+'\n'+t
 out=re.sub(r'^=== (\S+)\n(.*?)(?=^=== |\Z)',edit,s,flags=re.M|re.S)
 if out!=s:p.write_text(out)
